import random

UPPERCASE = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
DIGITS = "0123456789"


class Robot:
    _used_names = set()

    def __init__(self):
        self._name = None

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate_name()
        return self._name

    def reset(self):
        self._name = None

    @classmethod
    def _generate_name(cls):
        while True:
            name = "".join(
                random.choice(UPPERCASE) for _ in range(2)
            ) + "".join(
                random.choice(DIGITS) for _ in range(3)
            )
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name
